def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate full-width and full-height separator lines.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h))]
    sep_rows = [r for r in sep_rows if all(v == grid[r][0] for v in grid[r])]
    sep_cols = [c for c in sep_cols if all(grid[r][c] == grid[0][c] for r in range(h))]

    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    blocks = []
    for i in range(len(row_bounds) - 1):
        r0, r1 = row_bounds[i] + 1, row_bounds[i + 1]
        for j in range(len(col_bounds) - 1):
            c0, c1 = col_bounds[j] + 1, col_bounds[j + 1]
            blocks.append((r0, r1, c0, c1))

    # Use the block containing the most non-background colors as the repeated motif.
    def score(b):
        r0, r1, c0, c1 = b
        vals = [grid[r][c] for r in range(r0, r1) for c in range(c0, c1)]
        return len(set(vals) - {grid[0][0]})

    motif = max(blocks, key=score)
    r0, r1, c0, c1 = motif
    out = [row[:] for row in grid]
    for a, b, c, d in blocks:
        if b - a != r1 - r0 or d - c != c1 - c0:
            continue
        for r in range(b - a):
            for x in range(d - c):
                out[a + r][c + x] = grid[r0 + r][c0 + x]
    return out
