def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full-width uniform rows and full-height uniform columns are separators.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [
        c for c in range(w)
        if len({grid[r][c] for r in range(h)}) == 1
    ]

    row_edges = [-1] + sep_rows + [h]
    col_edges = [-1] + sep_cols + [w]
    blocks = []
    for i in range(len(row_edges) - 1):
        r0, r1 = row_edges[i] + 1, row_edges[i + 1]
        for j in range(len(col_edges) - 1):
            c0, c1 = col_edges[j] + 1, col_edges[j + 1]
            if r0 < r1 and c0 < c1:
                blocks.append((r0, r1, c0, c1))

    background = grid[0][0]

    def richness(block):
        r0, r1, c0, c1 = block
        return sum(grid[r][c] != background
                   for r in range(r0, r1) for c in range(c0, c1))

    source = max(blocks, key=richness)
    sr0, sr1, sc0, sc1 = source
    pattern = [grid[r][sc0:sc1] for r in range(sr0, sr1)]

    out = [row[:] for row in grid]
    for r0, r1, c0, c1 in blocks:
        if (r1 - r0, c1 - c0) != (sr1 - sr0, sc1 - sc0):
            continue
        for dr in range(r1 - r0):
            out[r0 + dr][c0:c1] = pattern[dr][:]
    return out
